import { marks } from './assets/identity.js';

// Isolated color-placement study. Keep the workflow and the approved Meridian identity fixed.
const directions = {
  paper: {letter:'00',name:'Current Paper',subtitle:'A baseline: white header and pale navigation.',colors:['#00338D','#1E49E2','#F5F6FA','#FFFFFF'],note:'The current Paper direction keeps almost the entire shell white. Its blue appears mostly in type, the small logo and actions. It is calm, but the parent brand has little visual presence.'},
  signature: {letter:'01',name:'Signature',subtitle:'Blue masthead. White working space. Recommended.',colors:['#00338D','#1E49E2','#EDF2FF','#F5F6FA','#FFFFFF'],note:'Recommended balance. A continuous KPMG-blue masthead makes the identity visible on every page, while navigation, tables and dialogs stay light. Use bright blue for the main action. Reverse the same Meridian artwork to white in the masthead.'},
  navigator: {letter:'02',name:'Navigator',subtitle:'Blue navigation. White masthead and canvas.',colors:['#00338D','#1E49E2','#EDF2FF','#F5F6FA','#FFFFFF'],note:'The strongest persistent blue presence. KPMG blue sits in the navigation column and the ATLAS corner; the header context and records remain white. This is more corporate and heavier than Signature, particularly in a long workspace.'},
  horizon: {letter:'03',name:'Horizon',subtitle:'Blue project context. White navigation and records.',colors:['#00338D','#1E49E2','#EAF0FA','#F5F6FA','#FFFFFF'],note:'Blue identifies the current project or local change set. A broad blue context band gives the page a KPMG character, with a white masthead and pale navigation. The Tenant entry uses the same blue for its introductory context. It is more expressive than Signature, while the data stays on white.'},
};
const params=new URLSearchParams(location.search);
let variant=Object.hasOwn(directions,params.get('variant'))?params.get('variant'):'signature';
let surface=['web','workbench','entry','identity','references'].includes(params.get('surface'))?params.get('surface'):'web';
const logo='meridian';
const wordmark='upper';
let query='', systemFilter='All systems', zoneFilter='All zones', filters=false, selected=null, grid=false, validated=false;
let tenantQuery='', tenantSelected=true;
let page='Projects', section='Input scope', dataset='Source objects';
let rows=[
  {name:'customer',description:'Customer identities and account details',system:'CRM',schema:'bronze_customer',count:12,updated:'Today, 09:42',status:'Ready'},
  {name:'orders',description:'Order headers and transaction totals',system:'Commerce',schema:'bronze_commerce',count:18,updated:'Today, 09:38',status:'Ready'},
  {name:'order_items',description:'Individual products within each order',system:'Commerce',schema:'bronze_commerce',count:9,updated:'Today, 09:38',status:'Ready'},
  {name:'product',description:'Product catalog and classification',system:'Catalog',schema:'bronze_catalog',count:16,updated:'Yesterday',status:'Review'},
  {name:'store',description:'Retail locations and regional hierarchy',system:'Commerce',schema:'bronze_commerce',count:8,updated:'Yesterday',status:'Ready'},
];
const sampleAttributes={
  customer:[['customer_id','BIGINT · Key','Unique customer identifier'],['customer_name','VARCHAR','Customer display name'],['email_address','VARCHAR','Primary contact email']],
  orders:[['order_id','BIGINT · Key','Unique order identifier'],['customer_id','BIGINT','Customer who placed the order'],['order_total','DECIMAL(18,2)','Total value of the order']],
  order_items:[['order_item_id','BIGINT · Key','Unique order line identifier'],['product_id','BIGINT','Product ordered on this line'],['quantity','INTEGER','Number of units ordered']],
  product:[['product_id','BIGINT · Key','Unique product identifier'],['product_name','VARCHAR','Product display name'],['category','VARCHAR','Product category']],
  store:[['store_id','BIGINT · Key','Unique store identifier'],['store_name','VARCHAR','Retail location name'],['region_code','VARCHAR','Regional reporting code']],
  payment:[['payment_id','BIGINT · Key','Unique payment identifier'],['order_id','BIGINT','Order being settled'],['payment_status','VARCHAR','Current settlement status']],
};
const root=document.querySelector('#root');
const icons={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',database:'M20 6c0 2-4 3-8 3S4 8 4 6s4-3 8-3 8 1 8 3ZM4 6v12c0 2 4 3 8 3s8-1 8-3V6M4 12c0 2 4 3 8 3s8-1 8-3',layers:'m3 7 9-4 9 4-9 4-9-4Zm0 5 9 4 9-4M3 17l9 4 9-4',message:'M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-5 3V6a2 2 0 0 1 1-2ZM8 9h8M8 13h5',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0ZM15 15l6 6',chevron:'m9 5 7 7-7 7',filter:'M4 6h16M7 12h10M10 18h4',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',folder:'M3 7V5h7l2 3h9v12H3V7Z',arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',back:'m14 5-7 7 7 7',settings:'M5 7h14M5 17h14M9 4v6M15 14v6'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(icons[name]||icons.layers).split('~').map(d=>`<path d="${d}"/>`).join('')}</svg>`;
const mark=(key=logo,size=32)=>`<svg class="atlas-symbol" width="${size}" height="${size}" viewBox="${marks[key].viewBox}" aria-hidden="true">${marks[key].body}</svg>`;
const brand=(key=logo)=>`<div class="brand ${wordmark==='upper'?'brand-uppercase':''}" aria-label="Atlas">${mark(key)}<span>${wordmark==='upper'?'ATLAS':'Atlas'}</span></div>`;
const button=(label,action,primary=false,ico='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${ico?icon(ico,16):''}${label}</button>`;
const navItems=[['Home','home'],['Metadata','database'],['Projects','layers'],['Prompts','message']];
function navigation(compact=false){return `<nav class="global-nav" aria-label="Workspace navigation">${navItems.map(([label,ico])=>`<button data-page="${label}" class="nav-link ${page===label?'active':''}" title="${label}" ${page===label?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></button>`).join('')}</nav>`;}
function workflow(vertical=false){const names=['Overview','Settings','Input scope','Context','Profiling','Enrichment','Analysis','Conceptual','Logical','Dimensional','Mapping','Code generation','Validation'];return `<nav class="workflow ${vertical?'vertical':''}" aria-label="Project sections">${names.map((name,i)=>`<button data-section="${name}" class="${section===name?'active':''}" ${section===name?'aria-current="page"':''}>${vertical?`<span class="step-index">${String(i+1).padStart(2,'0')}</span>`:''}<span>${name}</span>${['Profiling','Analysis','Conceptual'].includes(name)?'<i class="done-dot" aria-label="Results available"></i>':''}</button>`).join('')}</nav>`;}
function locationBar(){return `<div class="location"><span>Northwind Analytics</span><span class="slash">/</span><strong>${surface==='workbench'?'Local Workbench':'Customer 360'}</strong><span class="revision">r18</span></div>`;}
function account(){return `<div class="account"><span class="local-label">${surface==='workbench'?'Local workspace':'Architect'}</span><span class="avatar" aria-label="Alex Morgan">AM</span></div>`;}
function projectHeader(){return `<header class="project-heading"><div><div class="eyebrow">${surface==='workbench'?'LOCAL CHANGE SET':'PROJECT WORKSPACE'}</div><h1>${surface==='workbench'?'Customer metadata':'Customer 360'}</h1><p>${surface==='workbench'?'Review proposed changes against the downloaded snapshot.':'Customer identities, commerce and shared business definitions.'}</p></div><div class="project-status"><span class="live-dot"></span>${surface==='workbench'?'All changes local':'Tenant lock available'}<span class="meta-line">${surface==='workbench'?'Snapshot · today, 09:42':'Updated today at 09:42'}</span></div></header>`;}
function rail(){return `<div class="nav-label">WORKSPACE</div>${navigation()}<div class="project-shortcut"><span class="nav-label">CURRENT PROJECT</span><strong>Customer 360</strong><span>Customer & commerce</span><button data-section="Overview">View overview ${icon('arrow',14)}</button></div><div class="rail-foot"><span class="live-dot"></span>All systems operational</div>`;}
function webShell(){
  return `<div class="shell paper ${variant}"><header class="app-masthead">${brand()}${locationBar()}${account()}</header><aside class="main-rail">${rail()}</aside><main class="working-area">${projectHeader()}${workflow()}${workspace()}</main></div>`;
}
function workbench(){return `<div class="bench-shell paper ${variant}"><header class="app-masthead">${brand()}<div class="folder-location">${icon('folder',18)}<span>customer-360<span class="meta-line">Local Workbench</span></span></div><div class="bench-header-actions">${button(validated?'Validated':'Validate locally','validate',true,'check')}${account()}</div></header><div class="bench-context"><span><span class="live-dot"></span> Local directory connected</span><span>Northwind Analytics <b>/</b> Customer 360 <b>/</b> Revision 18</span></div><aside class="bench-rail"><div class="nav-label">WORKING AREA</div><button class="bench-area active" data-dataset="Source objects">${icon('database')} Metadata</button><button class="bench-area" data-dataset="Project entities">${icon('layers')} Project</button><div class="nav-label dataset-label">DATASETS</div>${['Source objects','Source attributes','Object relationships'].map((n,i)=>`<button data-dataset="${n}" class="dataset ${dataset===n?'active':''}"><span>${n}</span><small>${[5,63,4][i]}</small></button>`).join('')}<div class="rail-foot">Snapshot stays unchanged.</div></aside><main class="working-area">${projectHeader()}<div class="bench-tabs"><button data-dataset="Source objects" class="${dataset==='Source objects'?'active':''}">Snapshot <span>5</span></button><button data-action="changes">Change Set <span>1</span></button></div>${workspace()}</main><footer class="bench-footer"><span>${validated?'Validation complete · 5 records checked · no issues':'Review changes before staging.'}</span><span>Local only · synthetic records</span></footer></div>`;}
function workspace(){const special=page==='Prompts'?'Instruction library':page==='Metadata'?'Source objects':section==='Input scope'?dataset:section;const display=rows.filter(r=>(r.name+' '+r.description+' '+r.system).toLowerCase().includes(query.toLowerCase())&&(systemFilter==='All systems'||r.system===systemFilter)&&(zoneFilter==='All zones'||zoneFilter==='Bronze'));let inspected=selected?rows.find(r=>r.name===selected):null;return `<section class="records"><div class="records-heading"><div><h2>${special}</h2><p>${surface==='workbench'?'Downloaded snapshot and local proposals':section==='Input scope'?'Objects included in this project':'Review the project’s available records and results.'}</p></div><span class="record-count">${rows.length} objects</span></div><div class="toolbar"><label class="search">${icon('search',16)}<input aria-label="Search records" placeholder="Search objects…" value="${query.replaceAll('&','&amp;').replaceAll('"','&quot;')}"></label><div class="toolbar-actions">${button('Filters','filters',false,'filter')}${button(surface==='workbench'?'Review changes':'Add objects',surface==='workbench'?'changes':'add',true,'plus')}</div></div>${filters?`<div class="filters"><label>System<select id="system-filter">${['All systems','CRM','Commerce','Catalog'].map(value=>`<option ${systemFilter===value?'selected':''}>${value}</option>`).join('')}</select></label><label>Zone<select id="zone-filter">${['All zones','Bronze','Silver'].map(value=>`<option ${zoneFilter===value?'selected':''}>${value}</option>`).join('')}</select></label><button class="text-button" data-action="clear">Clear filters</button></div>`:''}<div class="records-body ${inspected?'with-inspector':''}"><div class="ledger"><table><caption class="sr-only">${special}</caption><thead><tr><th>Object</th><th>Source system</th><th>Attributes</th><th>Status</th><th aria-label="Details"></th></tr></thead><tbody>${display.map((r,i)=>`<tr class="${inspected?.name===r.name?'selected':''}"><td><button class="object-name" data-inspect="${r.name}">${icon('database',17)}<span>${r.name}<small>${r.description}</small></span></button></td><td><span>${r.system}</span><small>${r.schema}</small></td><td class="numeric">${r.count}</td><td><span class="status ${r.status==='Review'?'warning':''}"><i></i>${r.status}</span></td><td><button class="row-open" data-inspect="${r.name}" aria-label="Inspect ${r.name}">${icon('chevron',16)}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching records. Try another search.</td></tr>'}</tbody></table><div class="ledger-foot"><span>${display.length} of ${rows.length} objects</span><span>Metadata refreshed today, 09:42</span></div></div>${inspected?inspector(inspected):''}</div><div class="workspace-bottom"><span class="live-dot"></span>${surface==='workbench'?'Changes remain in this local workspace.':'Metadata is current. No pending changes.'}<button class="text-button" data-action="changes">View activity ${icon('arrow',14)}</button></div></section>`;}
function inspector(r){return `<aside class="inspector" aria-label="Object details"><header><span class="eyebrow">OBJECT DETAILS</span><button class="icon-button" data-action="close-details" aria-label="Close object details">${icon('close',16)}</button></header><div class="object-icon">${icon('database',24)}</div><h3>${r.name}</h3><p>${r.description}</p><span class="status"><i></i>Included in scope</span><dl><dt>Source system</dt><dd>${r.system}</dd><dt>Schema</dt><dd>${r.schema}</dd><dt>Zone</dt><dd>Bronze</dd><dt>Attributes</dt><dd>${r.count}</dd></dl><div class="inspector-section"><h4>Key attributes</h4>${sampleAttributes[r.name].map(([name,type])=>`<div><code>${name}</code><small>${type}</small></div>`).join('')}</div><button class="btn" data-action="attributes" data-object="${r.name}">View attributes ${icon('arrow',16)}</button></aside>`;}
function entry(){
 const tenantVisible='northwind analytics customer and commerce data'.includes(tenantQuery.toLowerCase().trim());
 return `<div class="entry paper ${variant}"><header class="app-masthead">${brand()}${account()}</header><main><div class="entry-side"><span class="eyebrow">YOUR WORKSPACE</span><h1>Everything starts<br>with a shared view.</h1><p>Choose the Tenant you want to work in.</p><div class="entry-motif" aria-hidden="true">${mark(logo,160)}</div></div><section class="tenant-choice"><span class="eyebrow">ATLAS / WORKSPACES</span><h2>Choose a Tenant</h2><label class="search">${icon('search',17)}<input placeholder="Search your workspaces" aria-label="Search tenants" value="${tenantQuery.replaceAll('&','&amp;').replaceAll('"','&quot;')}"></label>${tenantVisible?`<button class="tenant-row ${tenantSelected?'selected':''}" data-action="select-tenant" aria-pressed="${tenantSelected}"><span class="tenant-initial">NW</span><span><strong>Northwind Analytics</strong><small>Customer and commerce data</small></span>${tenantSelected?`<span class="selected-tick">${icon('check',18)}</span>`:''}</button>`:'<p class="empty" role="status">No matching workspaces. Try “Northwind”.</p>'}<div class="tenant-meta"><span>${tenantSelected&&tenantVisible?'Private workspace':'Choose a workspace to continue'}</span><span>Architect access</span></div><button class="btn primary enter-button" data-action="enter-tenant" ${tenantSelected&&tenantVisible?'':'disabled'}>Enter ATLAS ${icon('arrow',17)}</button><p class="entry-footnote">Signed in as Alex Morgan<br><span>alex.morgan@example.test</span></p></section></main><footer>ATLAS <span>Governed data. Shared understanding.</span></footer></div>`;
}
function identity(){return `<main class="identity-page"><header><div class="eyebrow">IDENTITY / OPTICAL REVIEW</div><h1>A single mark. Every surface.</h1><p>The approved Meridian mark and ATLAS wordmark stay identical in every option. Only the background and positive or reversed colour change.</p></header><div class="specimens"><section class="large-specimen ${grid?'grid-on':''}"><div class="specimen-label">MASTER VECTOR <button class="text-button" data-action="grid">${grid?'Hide grid':'Show grid'}</button></div>${mark(logo,176)}<div class="specimen-caption">One continuous color · 32 × 32 construction grid</div></section><section class="lockup-specimens"><div class="light-lockup">${brand()}<span>Positive / light surface</span></div><div class="dark-lockup">${brand()}<span>Reversed / dark surface</span></div><div class="sizes">${[16,20,24,32,48].map(n=>`<div>${mark(logo,n)}<span>${n}px</span></div>`).join('')}</div></section></div><section class="identity-applications"><h2>One identity, consistently applied</h2><div class="application-strip"><div><span>Web application</span>${brand()}</div><div><span>Local Workbench</span>${brand()}</div><div><span>Tenant entry</span>${brand()}</div><div class="app-icon-preview"><span>App icon & favicon</span><b>${mark(logo,32)}</b>${mark(logo,16)}</div></div></section><div class="identity-rules"><span>${icon('check',16)} Identical silhouette on light and dark</span><span>${icon('check',16)} No pale structural pieces or colored seams</span><span>${icon('check',16)} Same wordmark proportions everywhere</span></div></main>`;}
function references(){
 const refs=[
  ['KPMG Workbench','Blue identity, white reading areas','KPMG’s public Workbench page combines substantial blue sections with white content. This supports keeping a recognizable blue anchor around a light ATLAS workspace.','https://kpmg.com/us/en/capabilities-services/ai/kpmg-workbench.html'],
  ['KPMG public stylesheet','Use the actual palette','The current site defines KPMG blue #00338D, cobalt #1E49E2, white #FFFFFF, ink #0C233C and pale gray #F5F6FA. Keeping cobalt mainly for ATLAS actions is our design choice.','https://kpmg.com/kpmg-us/etc.clientlibs/kpmg/clientlibs/clientlib-site.lc-6e494438867998fc0f0645a6f90090e0-lc.min.css'],
 ];
 return `<main class="reference-page"><span class="eyebrow">RESEARCH / DESIGN RATIONALE</span><h1>Built from KPMG’s blues.<br>Balanced for work.</h1><p class="reference-intro">The blue is already right. Its visual presence needs work. Keep the approved Meridian and ATLAS identity, then give deep blue one confident area. Keep records white and reserve cobalt for the next action.</p><div class="references">${refs.map(([name,title,desc,url],i)=>`<a href="${url}" target="_blank" rel="noopener"><span class="reference-number">0${i+1}</span><div><span class="eyebrow">${name}</span><h2>${title}</h2><p>${desc}</p></div>${icon('arrow',22)}</a>`).join('')}</div><div class="direction-rationale"><span class="eyebrow">CURRENT STUDY / ${directions[variant].name}</span><p>${directions[variant].note}</p><div class="palette">${directions[variant].colors.map(c=>`<div><i style="background:${c}"></i><code>${c}</code></div>`).join('')}</div></div></main>`;
}
function render(){
  document.body.dataset.variant=variant;
  root.innerHTML=`<header class="review-header"><div class="review-title"><strong>Design review</strong><span>ATLAS · blue + white</span></div><nav aria-label="Preview surface">${[['web','Web app'],['workbench','Workbench'],['entry','Tenant entry'],['identity','Logo check'],['references','Why these blues']].map(([key,name])=>`<button data-surface="${key}" class="${surface===key?'active':''}" aria-pressed="${surface===key}">${name}</button>`).join('')}</nav><span class="prototype-label"><i></i>PROTOTYPE</span></header><div class="preview" data-surface="${surface}">${surface==='web'?webShell():surface==='workbench'?workbench():surface==='entry'?entry():surface==='identity'?identity():references()}</div><aside class="review-dock" aria-label="Design comparison"><button class="dock-arrow" data-action="previous" aria-label="Previous direction">${icon('back',18)}</button><div class="direction-buttons">${Object.entries(directions).map(([k,d])=>`<button data-variant="${k}" aria-pressed="${variant===k}"><small>${d.letter}</small>${d.name}</button>`).join('')}</div><button class="dock-arrow" data-action="next" aria-label="Next direction">${icon('chevron',18)}</button><button class="dock-info" data-surface="references" aria-label="View design rationale">i</button><p class="balance-note">${directions[variant].subtitle}</p></aside><div id="notice" role="status"></div><dialog id="add-dialog" aria-labelledby="add-title"><form method="dialog"><div class="dialog-heading"><div><span class="eyebrow">PROJECT INPUT SCOPE</span><h2 id="add-title">Add objects</h2></div><button aria-label="Close dialog" class="icon-button">${icon('close')}</button></div><p>Select an object to include in the prototype.</p><label class="candidate"><input type="checkbox" id="candidate"> <span><strong>payment</strong><small>Commerce · bronze_commerce · 11 attributes</small></span></label><footer><button class="btn" value="cancel">Cancel</button><button class="btn primary" id="confirm-add" value="add">Add selected</button></footer></form></dialog><dialog id="attributes-dialog" aria-labelledby="attributes-title"></dialog>`;
  const brandColor=getComputedStyle(document.body).getPropertyValue('--brand').trim();
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="${brandColor}" color="${brandColor}">${marks[logo].body}</svg>`;
  document.querySelector('#favicon').href='data:image/svg+xml,'+encodeURIComponent(svg);
  document.querySelector('meta[name="theme-color"]').content=brandColor;
}
function url(){history.replaceState(null,'',`?variant=${variant}&surface=${surface}`);}
function switchDirection(key){variant=key;url();render();}
function notify(message){const el=document.querySelector('#notice');el.textContent=message;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),3000);}
root.addEventListener('click',event=>{
 const target=event.target.closest('button');if(!target)return;
 if(target.dataset.variant){switchDirection(target.dataset.variant);root.querySelector(`[data-variant="${variant}"]`).focus();return;}
 if(target.dataset.surface){surface=target.dataset.surface;url();render();root.querySelector(`[data-surface="${surface}"]`).focus();window.scrollTo(0,0);return;}
  if(target.dataset.page){page=target.dataset.page;section=page==='Projects'?'Input scope':page==='Home'?'Overview':page;render();return;}
 if(target.dataset.section){section=target.dataset.section;render();return;}
 if(target.dataset.dataset){dataset=target.dataset.dataset;render();return;}
 if(target.dataset.inspect){selected=target.dataset.inspect;render();return;}
 const action=target.dataset.action;
 if(action==='previous'||action==='next'){const keys=Object.keys(directions);switchDirection(keys[(keys.indexOf(variant)+(action==='next'?1:keys.length-1))%keys.length]);root.querySelector(`[data-action="${action}"]`).focus();}
 else if(action==='filters'){filters=!filters;render();}
 else if(action==='close-details'){selected=null;render();}
 else if(action==='grid'){grid=!grid;render();}
  else if(action==='clear'){systemFilter='All systems';zoneFilter='All zones';render();}
 else if(action==='add')document.querySelector('#add-dialog').showModal();
 else if(action==='changes'){selected=rows[0].name;render();notify(surface==='workbench'?'1 local proposal · customer description updated':'No pending changes · metadata is current');}
 else if(action==='attributes'){
  const record=rows.find(row=>row.name===target.dataset.object);if(!record)return;
  const dialog=document.querySelector('#attributes-dialog');
  dialog.innerHTML=`<form method="dialog"><div class="dialog-heading"><div><span class="eyebrow">SAMPLE ATTRIBUTES</span><h2 id="attributes-title">${record.name}</h2></div><button class="icon-button" aria-label="Close attributes">${icon('close')}</button></div><p>Showing 3 representative attributes of ${record.count}. Synthetic metadata for this prototype.</p>${sampleAttributes[record.name].map(([name,type,description])=>`<div class="candidate"><span><strong>${name}</strong><small>${type} · ${description}</small></span></div>`).join('')}<footer><button class="btn primary" autofocus>Close</button></footer></form>`;
  dialog.showModal();
 }
 else if(action==='select-tenant'){tenantSelected=!tenantSelected;render();root.querySelector('[data-action="select-tenant"]').focus();}
 else if(action==='enter-tenant'&&tenantSelected){surface='web';page='Projects';section='Input scope';url();render();}
 else if(action==='validate'){validated=true;render();notify('Local validation complete. No issues in the prototype records.');}
});
root.addEventListener('input',event=>{
 const label=event.target.getAttribute('aria-label');
 if(label!=='Search records'&&label!=='Search tenants')return;
 const pos=event.target.selectionStart;
 if(label==='Search records')query=event.target.value;else tenantQuery=event.target.value;
 render();const input=root.querySelector(`[aria-label="${label}"]`);input.focus();input.setSelectionRange(pos,pos);
});
root.addEventListener('change',event=>{
 const {id,value}=event.target;
 if(id==='system-filter'||id==='zone-filter'){
  if(id==='system-filter')systemFilter=value;else zoneFilter=value;
  render();root.querySelector(`#${id}`).focus();
 }
});
root.addEventListener('close',event=>{if(event.target.id==='add-dialog'&&event.target.returnValue==='add'&&document.querySelector('#candidate').checked){if(!rows.some(r=>r.name==='payment'))rows.push({name:'payment',description:'Payment status and settlement details',system:'Commerce',schema:'bronze_commerce',count:11,updated:'Just now',status:'Ready'});render();notify('payment added to this prototype only.');}},true);
document.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key)||event.target.closest('input,textarea,select,button,[contenteditable="true"],nav,dialog'))return;event.preventDefault();const keys=Object.keys(directions);switchDirection(keys[(keys.indexOf(variant)+(event.key==='ArrowRight'?1:keys.length-1))%keys.length]);});
window.addEventListener('popstate',()=>location.reload());
render();url();
